export function formatDnd5eSpellDetails(entry: { category: string; summary: string; castingTime?: string; range?: string; components?: string; duration?: string; ritual?: boolean; savingThrow?: string }): string {
  if (entry.category !== "magia") return entry.summary;
  return [
    entry.castingTime && `conjuração: ${entry.castingTime}`,
    entry.range && `alcance: ${entry.range}`,
    entry.components && `componentes: ${entry.components}`,
    entry.duration && `duração: ${entry.duration}`,
    entry.savingThrow && `resistência: ${entry.savingThrow}`,
    entry.ritual && "ritual",
  ].filter(Boolean).join(" · ") || entry.summary;
}

